const toKey = ([x, y]: Cell): string => `${x},${y}`;

type NeighborTally = { cell: Cell; liveNeighborCount: number };

function tallyLiveNeighborsForEachCandidate(liveCells: Cell[]): Iterable<NeighborTally> {
  const tallies = new Map<string, NeighborTally>();
  for (const [x, y] of liveCells) {
    for (const [dx, dy] of NEIGHBOR_OFFSETS) {
      const cell: Cell = [x + dx, y + dy];
      const key = toKey(cell);
      tallies.set(key, { cell, liveNeighborCount: (tallies.get(key)?.liveNeighborCount ?? 0) + 1 });
    }
  }
  return tallies.values();
}

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const aliveKeys = new Set(liveCells.map(toKey));
  const isAliveNextGen = ({ cell, liveNeighborCount }: NeighborTally): boolean =>
    liveNeighborCount === 3 || (liveNeighborCount === 2 && aliveKeys.has(toKey(cell)));
  return Array.from(tallyLiveNeighborsForEachCandidate(liveCells))
    .filter(isAliveNextGen)
    .map(({ cell }) => cell);
}

